interface LeftUnits { default String units() { return "m"; } }
interface RightUnits { default String units() { return "metres"; } }
class CombinedUnits implements LeftUnits, RightUnits {
    public String units() { return LeftUnits.super.units() + "/" + RightUnits.super.units(); }
}
public class DefaultConflictResolutionDemo {
    public static void main(String[] args) { System.out.println(new CombinedUnits().units()); }
}
